function normalize(text) {
  return text.toLowerCase().replace(/[^a-z0-9\s]/g, ' ');
}

const SYNTHETIC_HINTS = [
  'perfectly curated',
  'cinematic',
  'stunningly',
  'generated by a prompt',
  'beautifully crafted',
  'highly polished',
  'vividly captures',
  'idealized',
  'ultra realistic',
  'perfect harmony',
  'synthetic',
];

const AUTHENTIC_HINTS = [
  'remember',
  'still remember',
  'i felt',
  'my hands',
  'the smell',
  'the sound',
  'the rain',
  'cold',
  'warm',
  'last night',
  'when i',
  'i was',
];

function analyzeNeuralAuthenticity(payload) {
  const content = payload.content ?? '';
  const normalized = normalize(content);
  const metadata = payload.memoryMetadata ?? {};
  const signals = [];

  let score = 0.2;

  const hasSpecificPersonalDetails = /\b(i|my|remember|felt|smell|sound|rain|cold|warm|hands|voice|touch|last night|when i|still remember)\b/.test(normalized);
  if (hasSpecificPersonalDetails) {
    score += 0.35;
    signals.push('personal memory details detected');
  }

  const hasSensoryMedia = Boolean(
    metadata?.sensory?.visual?.length || metadata?.sensory?.audio?.length || metadata?.sensory?.haptic?.length || metadata?.sensory?.olfactory?.length || metadata?.sensory?.gustatory?.length,
  );
  if (hasSensoryMedia) {
    score += 0.2;
    signals.push('sensory media present');
  }

  const hasEmotionalContext = Boolean(metadata?.emotions && Object.values(metadata.emotions).some((value) => Number(value) > 0));
  if (hasEmotionalContext) {
    score += 0.15;
    signals.push('emotional context present');
  }

  const hasLocationContext = Boolean(metadata?.context?.location?.name || metadata?.context?.activity);
  if (hasLocationContext) {
    score += 0.1;
    signals.push('situational context present');
  }

  const syntheticHits = SYNTHETIC_HINTS.filter((hint) => normalized.includes(hint));
  if (syntheticHits.length > 0) {
    score -= 0.35 + syntheticHits.length * 0.05;
    signals.push(`synthetic phrasing detected: ${syntheticHits.join(', ')}`);
  }

  const authenticHits = AUTHENTIC_HINTS.filter((hint) => normalized.includes(hint));
  if (authenticHits.length > 0) {
    score += 0.05 * Math.min(authenticHits.length, 4);
    signals.push(`authentic memory cues: ${authenticHits.slice(0, 4).join(', ')}`);
  }

  const clampedScore = Math.max(0, Math.min(1, score));
  const verdict = clampedScore >= 0.7 ? 'likely_authentic' : clampedScore <= 0.4 ? 'likely_synthetic' : 'needs_review';

  return {
    score: Number(clampedScore.toFixed(3)),
    verdict,
    signals: signals.length > 0 ? signals : ['no strong authenticity markers detected'],
    confidence: Number(Math.min(0.99, 0.6 + clampedScore * 0.35).toFixed(3)),
  };
}

module.exports = { analyzeNeuralAuthenticity };
